{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.interest import compound"
  ],
  "tests": [
    {
      "name": "test_compound_example_from_task",
      "intent": "the example given in the task: 1000 at 5% for 2 years should be 1102.50",
      "code": "# intent: the example given in the task: 1000 at 5% for 2 years should be 1102.50\ndef test_compound_example_from_task():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 2) == Decimal(\"1102.50\")\n"
    },
    {
      "name": "test_compound_one_year_applies_single_compounding",
      "intent": "one year applies exactly one compounding period",
      "code": "# intent: one year applies exactly one compounding period\ndef test_compound_one_year_applies_single_compounding():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 1) == Decimal(\"1050.00\")\n"
    },
    {
      "name": "test_compound_three_years_compounds_three_times",
      "intent": "three years compounds three times, not two",
      "code": "# intent: three years compounds three times, not two\ndef test_compound_three_years_compounds_three_times():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 3) == Decimal(\"1157.63\")\n"
    },
    {
      "name": "test_compound_zero_years_returns_principal",
      "intent": "zero years returns the principal unchanged",
      "code": "# intent: zero years returns the principal unchanged\ndef test_compound_zero_years_returns_principal():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 0) == Decimal(\"1000.00\")\n"
    },
    {
      "name": "test_compound_negative_years_raises_value_error",
      "intent": "negative years are rejected with ValueError",
      "code": "# intent: negative years are rejected with ValueError\ndef test_compound_negative_years_raises_value_error():\n    with pytest.raises(ValueError):\n        compound(Decimal(\"1000.00\"), Decimal(\"5\"), -1)\n"
    },
    {
      "name": "test_compound_rounds_to_cents_at_end",
      "intent": "result is rounded to cents (two decimal places) at the end",
      "code": "# intent: result is rounded to cents (two decimal places) at the end\ndef test_compound_rounds_to_cents_at_end():\n    assert compound(Decimal(\"1000.00\"), Decimal(\"5\"), 2) == Decimal(\"1102.50\")\n"
    }
  ]
}
